INSERT INTO DimCompany (SK_CompanyID, CompanyID, Status, Name, Industry, SPrating, isLowGrade, CEO, Description, FoundingDate, AddressLine1, AddressLine2, PostalCode, City, StateProv, Country, IsCurrent, BatchID, EffectiveDate, EndDate) SELECT CAST(ROW_NUMBER() OVER (ORDER BY c.CompanyID, c.EffectiveDate) AS INT) AS SK_CompanyID, CAST(CompanyID AS INT) AS CompanyID, CAST(Status AS TEXT) AS Status, CAST(Name AS TEXT) AS Name, CAST(Industry AS TEXT) AS Industry, CAST(SPrating AS TEXT) AS SPrating, CAST(isLowGrade AS BOOLEAN) AS isLowGrade, CAST(CEO AS TEXT) AS CEO, CAST(Description AS TEXT) AS Description, CAST(FoundingDate AS DATE) AS FoundingDate, CAST(AddressLine1 AS TEXT) AS AddressLine1, CAST(AddressLine2 AS TEXT) AS AddressLine2, CAST(PostalCode AS TEXT) AS PostalCode, CAST(City AS TEXT) AS City, CAST(StateProv AS TEXT) AS StateProv, CAST(Country AS TEXT) AS Country, CAST(c.EffectiveDate = MAX(c.EffectiveDate) OVER (PARTITION BY c.CompanyID) AS BOOLEAN) AS IsCurrent, CAST(1 AS DECIMAL(5, 0)) AS BatchID, CAST(EffectiveDate AS DATE) AS EffectiveDate, CAST(COALESCE(CAST(LEAD(c.EffectiveDate) OVER (PARTITION BY c.CompanyID ORDER BY c.EffectiveDate) AS DATE), CAST('9999-12-31' AS DATE)) AS DATE) AS EndDate FROM (SELECT CAST(CMP.CIK AS INT) AS CompanyID, CAST(CMP.CompanyName AS TEXT) AS Name, CAST(CMP.SPrating AS TEXT) AS SPrating, CMP.CEOname AS CEO, LEFT(CMP.Description, 150) AS Description, TRY_CAST(NULLIF(CMP.FoundingDate, '') AS DATE) AS FoundingDate, CAST(CMP.AddrLine1 AS TEXT) AS AddressLine1, NULLIF(CMP.AddrLine2, '') AS AddressLine2, CMP.PostalCode AS PostalCode, CMP.City AS City, CMP.StateProvince AS StateProv, TRIM(CMP.Country) AS Country, S.ST_NAME AS Status, CAST(I.IN_NAME AS TEXT) AS Industry, CMP.SPrating IN ('BB+', 'BB', 'BB-', 'B+', 'B', 'B-', 'CCC+', 'CCC', 'CCC-', 'CC', 'C', 'D') AS isLowGrade, NULL AS EffectiveDate FROM Source.FinwireCMP AS CMP, Source.StatusType AS S, Source.Industry AS I WHERE CMP.Status = S.ST_ID AND CMP.IndustryID = I.IN_ID) AS c;
